import React, { useState, useEffect } from "react";
import { Bar } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const EmployeeList = () => {
  const [employees, setEmployees] = useState([]);
  const [showChart, setShowChart] = useState(false);

  useEffect(() => {
    // Fetch data from backend
    fetch("https://backend.jotish.in/backend_dev/gettabledata.php")
      .then((res) => res.json())
      .then((data) => {
        // Map the backend data into an array of objects
        const mappedData = data.TABLE_DATA.data.map((item, index) => ({
          id: index + 1,
          name: item[0],
          role: item[1],
          location: item[2],
          employeeId: item[3],
          date: item[4],
          salary: Number(item[5].replace(/[$,]/g, "")), // convert "$320,800" → 320800
          photo: "https://via.placeholder.com/50",
        }));
        setEmployees(mappedData);
      })
      .catch((err) => console.error("Error fetching data:", err));
  }, []);

  // Chart data
  const chartData = {
    labels: employees.map((e) => e.name),
    datasets: [
      {
        label: "Salary",
        data: employees.map((e) => e.salary),
        backgroundColor: "rgba(75, 192, 192, 0.6)",
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    plugins: {
      legend: { position: "top" },
      title: { display: true, text: "Employee Salary Chart" },
    },
  };

  return (
    <div>
      <h1>Employee List</h1>
      <button onClick={() => setShowChart(true)}>View Salary Chart</button>
      <button onClick={() => setShowChart(false)}>Hide Chart</button>

      <table border="1" cellPadding="8" style={{ marginTop: "20px" }}>
        <thead>
          <tr>
            <th>Photo</th>
            <th>Name</th>
            <th>Role</th>
            <th>Location</th>
            <th>ID</th>
            <th>Date</th>
            <th>Salary</th>
          </tr>
        </thead>
        <tbody>
          {employees.map((emp) => (
            <tr key={emp.id}>
              <td>
                <img src={emp.photo} alt={emp.name} width="50" height="50" />
              </td>
              <td>{emp.name}</td>
              <td>{emp.role}</td>
              <td>{emp.location}</td>
              <td>{emp.employeeId}</td>
              <td>{emp.date}</td>
              <td>${emp.salary.toLocaleString()}</td>
            </tr>
          ))}
        </tbody>
      </table>

      {showChart && (
        <div style={{ width: "70%", marginTop: "30px" }}>
          <Bar data={chartData} options={chartOptions} />
        </div>
      )}
    </div>
  );
};

export default EmployeeList;
